-- 2026-10-22 — Inspection et hivernage par ouvrage. AJOUTS SEULEMENT (aucune colonne retirée, aucune donnée modifiée).
--  * gabarits_hivernage : listes d'hivernement par type d'ouvrage (Piscine = le formulaire papier, Jeux d'eau, Fontaine),
--    modifiables dans sa-admin › Hivernage › Gabarits. Vide = sa-terrain et sa-admin prennent ceux de src/hivernage/checklist.js.
--  * ouvrage_ajustements : étapes et points retirés (« Ne s'applique pas ici ») ou ajoutés pour un site / un ouvrage,
--    par le technicien (sa-terrain) ou le bureau (sa-admin). Jamais supprimés : annulés (actif = false) avec qui et quand.
--  * inspection_points.bassin_id / site_id : point propre à un ouvrage (type_code '_ouvrage', ignoré par les anciennes versions).
-- Même niveau d'accès que inspection_points (anon et authenticated, comme après CORRECTIF_2026-10-20_politiques_connectes.sql).

create table if not exists public.gabarits_hivernage (
  code text primary key,
  nom text not null,
  types jsonb not null default '[]'::jsonb,       -- types_bassin.code et bassin.type qui prennent ce gabarit par défaut
  sections jsonb not null,                        -- [{ id, titre, col, col2?, num?, commun?, items: [{ n?, t, b?, crit?, g? }] }]
  conseils jsonb not null default '[]'::jsonb,
  alerte text not null default '',
  ordre integer not null default 0,
  actif boolean not null default true,
  updated_at timestamptz not null default now()
);

create table if not exists public.ouvrage_ajustements (
  id text primary key,
  site_id text not null,
  bassin_id text,                                 -- null = tout le site (section commune, site sans bassin déclaré)
  domaine text not null check (domaine in ('hiv','insp')),
  action text not null check (action in ('exclure','ajouter')),
  ref text,                                       -- exclure : « jeuxdeau:p2-3 » (hivernage) ou id du point (inspection)
  texte text,                                     -- ajouter : libellé de l'étape
  section text,                                   -- ajouter : section du gabarit (p1…p5)
  crit boolean not null default false,
  actif boolean not null default true,
  par text, par_nom text, cree_le timestamptz not null default now(),
  annule_par text, annule_par_nom text, annule_le timestamptz
);
create index if not exists ouvrage_ajustements_site on public.ouvrage_ajustements (site_id) where actif;

alter table if exists public.inspection_points add column if not exists bassin_id text;
alter table if exists public.inspection_points add column if not exists site_id text;

alter table public.gabarits_hivernage enable row level security;
alter table public.ouvrage_ajustements enable row level security;
do $$ declare t text; r text; begin
  foreach t in array array['gabarits_hivernage','ouvrage_ajustements'] loop
    foreach r in array array['anon','authenticated'] loop
      if not exists (select 1 from pg_policies where schemaname='public' and tablename=t and policyname=t||'_select_'||r) then
        execute format('create policy %I on public.%I for select to %I using (true)', t||'_select_'||r, t, r);
        execute format('create policy %I on public.%I for insert to %I with check (true)', t||'_insert_'||r, t, r);
        execute format('create policy %I on public.%I for update to %I using (true) with check (true)', t||'_update_'||r, t, r);
      end if;
    end loop;
  end loop;
end $$;

-- Gabarits de départ (Jeux d'eau et Fontaine : premier jet à valider par Soucy Aquatik)
insert into public.gabarits_hivernage (code, nom, types, sections, conseils, alerte, ordre) values
  ('piscine', 'Piscine', '["piscine","RE","ME","PA","GEN"]'::jsonb, '[{"id":"secu","titre":"Sécurité et préparation","col":"Vérification","commun":true,"items":[{"t":"EPI portés par toute l’équipe (bottes, gants, lunettes, protection auditive si compresseur)"},{"t":"Alimentation électrique des pompes, chauffe-eau et système de traitement coupée et verrouillée"},{"t":"Zone de travail délimitée et accès public bloqué (cônes, ruban)"},{"t":"Plan du parc revu : emplacement des valves, drains, écumoires et salle mécanique"},{"t":"Matériel et antigel biodégradable en quantité suffisante sur place (voir section 8)"},{"t":"Météo vérifiée : travaux prévus dans une fenêtre sans gel ni pluie battante"}]},{"id":"p1","titre":"Phase 1 — Vidange","col":"Tâche","num":true,"items":[{"n":"1","t":"Vidanger le bassin au complet (section « Vidange du bassin »)","crit":true},{"n":"14","t":"Ouvrir toutes les vannes de vidange de la salle mécanique"},{"n":"15","t":"Vidanger les filtres (bouchon au bas du filtre), remettre les bouchons, valves à 50 %"},{"n":"16","t":"Vidanger les chauffe-eau et/ou thermopompes (protéger de la neige et de la glace si extérieur)"},{"n":"17","t":"Vidanger les tamis de pompes (retirer les bouchons de drainage)"},{"n":"20","t":"Vidanger les produits chimiques des réservoirs (niveau le plus bas possible)"},{"n":"21","t":"Rincer les conduites d’injection en pompant de l’eau, puis vidanger. Démonter injecteurs et les ranger"},{"n":"22","t":"Dévisser les clapets anti-retour à la sortie des pompes pour évacuer l’eau de la colonne"}]},{"id":"p2","titre":"Phase 2 — Retrait et démontage","col":"Tâche","num":true,"items":[{"n":"2","t":"Retirer les boules et anneaux de serrage des retours d’eau"},{"n":"3","t":"Retirer grilles de drain de fond, paniers d’écumoires, bouchons de bronze de prise d’aspiration (et vase communicant)"},{"n":"4","t":"Enlever toutes les échelles, équipements de plage, lumières et les remiser"},{"n":"23","t":"Débrancher et démonter le système de traitement automatisé. Sondes ORP, pH et conductivité dans un liquide de remisage"},{"n":"24","t":"Isoler, drainer et retirer le double clapet DAR, réducteur de pression et anti-bélier (si présents) hors du gel"}]},{"id":"p3","titre":"Phase 3 — Protection des conduits et antigel","col":"Tâche","num":true,"items":[{"n":"5","t":"Aspirer l’eau des conduits vers la salle mécanique (aspirateur de chantier) ou souffler à l’air comprimé"},{"n":"6","t":"Ajouter l’antigel biodégradable : drain de fond, retour d’eau, écumoire, aspirateur, vase communicant et conduit de lumière"},{"n":"7","t":"Installer les bouchons expansibles dans les drains de fond"},{"n":"8","t":"Installer bouchons filetés 1 ½ po NPT sur sorties de retour et conduits de lumière"},{"n":"9","t":"Installer bouchons filetés 2 po NPT sur les prises d’aspiration (si présentes)"},{"n":"10","t":"Installer bouchons filetés 1 ½ po NPT dans les deux ouvertures au fond de chaque écumoire (voir schéma)"},{"n":"11","t":"Installer les ensembles protecteurs en styromousse à l’intérieur des écumoires"},{"n":"12","t":"Mettre les ensembles de styromousse dans la réserve de drain de fond.","b":"VALIDER l’étanchéité et le bon fonctionnement du clapet de tige hydrostatique","crit":true}]},{"id":"p4","titre":"Phase 4 — Remise d’eau contrôlée","col":"Tâche","num":true,"items":[{"n":"13","t":"Remettre de l’eau dans le bassin jusqu’à 16 po sous les retours.","b":"Vitesse de remplissage : 1 po/heure","crit":true},{"n":"18","t":"Remettre les bouchons de drainage sur les tamis et remplir de lubrifiant (Lubrigel) jusqu’au niveau des joints mécaniques"},{"n":"19","t":"Installer le couvercle sur chaque tamis (éviter l’évaporation de l’antigel)"}]},{"id":"p5","titre":"Phase 5 — Vérifications finales","col":"Vérification","num":true,"items":[{"n":"25","t":"Revérifier tout le système : aucune valve oubliée ouverte ou fermée à tort. La plupart des valves ouvertes sont à 50 %","crit":true},{"n":"—","t":"Tuyauterie vide ou avec antigel, selon la configuration. Aucun point bas où l’eau peut stagner"},{"n":"—","t":"Bouchons de 1 ½ po et 2 po installés et serrés, téflon sur les filets"},{"n":"—","t":"Équipements remisés (échelles, lumières, pièces) et identifiés pour le printemps"},{"n":"—","t":"Système de traitement remisé, sondes dans liquide de remisage"},{"n":"—","t":"Photos prises : salle mécanique, valves, bouchons, niveau d’eau du bassin"},{"n":"—","t":"Zone nettoyée, matériel rangé, aucun déchet chimique laissé sur place"}]},{"id":"mat","titre":"Matériel et pièces","col":"Matériel","col2":"Pièces de rechange","commun":true,"items":[{"t":"Antigel biodégradable"},{"t":"Pinces et tournevis divers"},{"t":"Téflon"},{"t":"Pompe à puisard et boyau"},{"t":"Ensembles styromousse (écumoires et drains de fond)"},{"t":"Corde pour fichier (lumières)"},{"t":"Aspirateur de chantier (shop-vac)"},{"t":"Clapet de tige hydrostatique (si piscine l’exige)","g":2},{"t":"Bouchons 1 ½ po NPT","g":2},{"t":"Bouchons 2 po NPT","g":2},{"t":"Bouchons expansibles (drains de fond)","g":2},{"t":"Lubrigel (lubrifiant tamis de pompes)","g":2},{"t":"Couvercles de tamis","g":2},{"t":"Bouchons de drainage de tamis","g":2}]},{"id":"form","titre":"Formation des employés","col":"Sujet de formation","commun":true,"items":[{"t":"Séquence complète de l’hivernement (phases 1 à 5) et logique de l’ordre des étapes"},{"t":"Identification des valves : celles qui se ferment et celles qui restent à 50 %"},{"t":"Installation des bouchons filetés et expansibles, dont les bouchons 1 ½ po et 2 po"},{"t":"Clapet de tige hydrostatique : test d’étanchéité et de fonctionnement"},{"t":"Remise d’eau à 1 po/heure et contrôle du niveau de 16 po"},{"t":"Manipulation sécuritaire de l’antigel, des produits chimiques et de l’air comprimé"},{"t":"Démonstration pratique réalisée sur le site, avec évaluation des participants"}]}]'::jsonb, '["L’idée de base d’un hivernement est d’éviter que les tuyaux gèlent et se cassent, et que le gel du sol soulève la piscine.","Selon la configuration, il n’est pas nécessaire de remplir toute la tuyauterie d’antigel. Dès qu’on voit l’antigel sortir à l’autre extrémité de la conduite soufflée, on peut arrêter et mettre les bouchons."]'::jsonb, 'L’HIVERNEMENT N’EST PAS UNE COURSE. UNE MAUVAISE EXÉCUTION PEUT AVOIR DES CONSÉQUENCES DE PLUSIEURS MILLIERS DE DOLLARS.', 1),
  ('jeuxdeau', 'Jeux d’eau', '["jeuxdeau","JE"]'::jsonb, '[{"id":"secu","titre":"Sécurité et préparation","col":"Vérification","commun":true,"items":[{"t":"EPI portés par toute l’équipe (bottes, gants, lunettes, protection auditive si compresseur)"},{"t":"Alimentation électrique des pompes, du contrôleur et du système de traitement coupée et verrouillée"},{"t":"Zone de travail délimitée et accès public bloqué (cônes, ruban)"},{"t":"Plan du site revu : bassin d’équilibre, salle mécanique, collecteurs, valves et lignes d’alimentation de chaque jeu"},{"t":"Météo vérifiée : travaux prévus dans une fenêtre sans gel ni pluie battante"}]},{"id":"p1","titre":"Phase 1 — Arrêt et isolement","col":"Tâche","num":true,"items":[{"n":"1","t":"Mettre le contrôleur des jeux (séquenceur) hors service et désactiver le bouton d’activation ou le détecteur"},{"n":"2","t":"Fermer l’entrée d’eau potable et la valve d’appoint du bassin d’équilibre","crit":true},{"n":"3","t":"Isoler, drainer et retirer le dispositif antirefoulement (DAR) et le réducteur de pression, puis les ranger hors du gel","crit":true},{"n":"4","t":"Couper et cadenasser les pompes, le système UV et le contrôleur de chimie"}]},{"id":"p2","titre":"Phase 2 — Vidange","col":"Tâche","num":true,"items":[{"n":"5","t":"Vidanger le bassin d’équilibre au complet (pompe submersible) et retirer les débris et le sable"},{"n":"6","t":"Ouvrir les drains bas des collecteurs et toutes les valves (manuelles et solénoïdes) des jeux"},{"n":"7","t":"Vidanger les filtres, les tamis de pompes, la chambre UV et l’échangeur (retirer les bouchons de drainage)"},{"n":"8","t":"Retirer la lampe UV et le manchon de quartz (si présents) et les ranger hors du gel"},{"n":"9","t":"Vidanger les réservoirs de produits chimiques, rincer les conduites d’injection. Sondes ORP et pH dans un liquide de remisage"}]},{"id":"p3","titre":"Phase 3 — Purge des conduites","col":"Tâche","num":true,"items":[{"n":"10","t":"Souffler chaque ligne de jeu à l’air comprimé, une à la fois, jusqu’à ce qu’il ne sorte plus que de l’air.","b":"Respecter la pression maximale du fabricant","crit":true},{"n":"11","t":"Souffler les conduites des drains de surface vers le bassin d’équilibre"},{"n":"12","t":"Ajouter de l’antigel biodégradable dans les siphons et les points bas qui ne se vident pas"},{"n":"13","t":"Laisser les valves des collecteurs dans la position d’hiver prévue (ouvertes ou à 50 %)"}]},{"id":"p4","titre":"Phase 4 — Protection des équipements de surface","col":"Tâche","num":true,"items":[{"n":"14","t":"Retirer ou capuchonner les buses et gicleurs démontables, les ranger identifiés pour le printemps"},{"n":"15","t":"Couvrir les drains de surface (sable, feuilles, débris)"},{"n":"16","t":"Refermer et verrouiller les trappes du bassin d’équilibre et de la chambre des valves"},{"n":"17","t":"Installer l’affiche « Jeux d’eau fermés pour l’hiver »"}]},{"id":"p5","titre":"Phase 5 — Vérifications finales","col":"Vérification","num":true,"items":[{"n":"18","t":"Revérifier tout le système : eau potable fermée, aucune ligne pleine, valves dans la position d’hiver","crit":true},{"n":"—","t":"Contrôleur programmé hors saison, disjoncteurs identifiés"},{"n":"—","t":"Photos prises : salle mécanique, collecteurs, bassin d’équilibre vide, valves"},{"n":"—","t":"Zone nettoyée, matériel rangé, aucun déchet chimique laissé sur place"}]},{"id":"mat","titre":"Matériel et pièces","col":"Matériel","col2":"Pièces de rechange","commun":true,"items":[{"t":"Compresseur, boyaux et raccords de soufflage"},{"t":"Pompe à puisard et boyau"},{"t":"Antigel biodégradable"},{"t":"Pinces et tournevis divers"},{"t":"Téflon"},{"t":"Capuchons de buses","g":2},{"t":"Couvercles de drains de surface","g":2},{"t":"Joints et bouchons de drainage","g":2}]},{"id":"form","titre":"Formation des employés","col":"Sujet de formation","commun":true,"items":[{"t":"Séquence complète de l’hivernement des jeux d’eau (phases 1 à 5)"},{"t":"Identification des lignes de chaque jeu et des valves du collecteur"},{"t":"Soufflage sécuritaire à l’air comprimé (pression, protection des yeux et des oreilles)"},{"t":"Démonstration pratique réalisée sur le site, avec évaluation des participants"}]}]'::jsonb, '["Une ligne de jeu qui garde de l’eau peut éclater au premier gel : on souffle jusqu’à ce qu’il ne sorte plus que de l’air, une ligne à la fois."]'::jsonb, 'L’HIVERNEMENT N’EST PAS UNE COURSE. UNE MAUVAISE EXÉCUTION PEUT AVOIR DES CONSÉQUENCES DE PLUSIEURS MILLIERS DE DOLLARS.', 2),
  ('fontaine', 'Fontaine', '["fontaine","FO"]'::jsonb, '[{"id":"secu","titre":"Sécurité et préparation","col":"Vérification","commun":true,"items":[{"t":"EPI portés par toute l’équipe (bottes, gants, lunettes, protection auditive si compresseur)"},{"t":"Alimentation électrique des pompes, du contrôleur et du système de traitement coupée et verrouillée"},{"t":"Zone de travail délimitée et accès public bloqué (cônes, ruban)"},{"t":"Plan du site revu : bassin ou vasque, réservoir, salle mécanique, valves et alimentation des buses"},{"t":"Météo vérifiée : travaux prévus dans une fenêtre sans gel ni pluie battante"}]},{"id":"p1","titre":"Phase 1 — Arrêt et isolement","col":"Tâche","num":true,"items":[{"n":"1","t":"Arrêter les pompes, l’éclairage et la minuterie, puis couper et cadenasser l’alimentation électrique"},{"n":"2","t":"Fermer l’appoint d’eau automatique (flotteur ou solénoïde) et l’entrée d’eau potable","crit":true},{"n":"3","t":"Isoler, drainer et retirer le dispositif antirefoulement (DAR) et le ranger hors du gel","crit":true}]},{"id":"p2","titre":"Phase 2 — Vidange et nettoyage","col":"Tâche","num":true,"items":[{"n":"4","t":"Vidanger le bassin (ou la vasque) et le réservoir au complet"},{"n":"5","t":"Nettoyer le fond et les parois : débris, algues et dépôts de calcaire"},{"n":"6","t":"Vidanger les pompes, les filtres et les tamis (retirer les bouchons de drainage)"},{"n":"7","t":"Retirer la pompe submersible (si présente), la nettoyer et la remiser selon les directives du fabricant"},{"n":"8","t":"Vidanger les réservoirs de produits chimiques et rincer les conduites d’injection (si présents)"}]},{"id":"p3","titre":"Phase 3 — Démontage et purge","col":"Tâche","num":true,"items":[{"n":"9","t":"Retirer les buses et les jets, les nettoyer et les ranger identifiés pour le printemps"},{"n":"10","t":"Souffler à l’air comprimé chaque conduite d’alimentation des buses jusqu’à ce qu’il ne sorte plus que de l’air","crit":true},{"n":"11","t":"Retirer les luminaires submersibles ou vérifier leur étanchéité selon le fabricant"},{"n":"12","t":"Ajouter de l’antigel biodégradable dans les siphons et les points bas qui ne se vident pas"}]},{"id":"p4","titre":"Phase 4 — Protection","col":"Tâche","num":true,"items":[{"n":"13","t":"Installer les bouchons sur les sorties de buses et sur l’appoint d’eau"},{"n":"14","t":"Laisser le drain du bassin ouvert (eau de pluie et de fonte) ou installer la couverture d’hiver, selon la fontaine"},{"n":"15","t":"Protéger les éléments décoratifs (housse, panneaux) contre le gel et la neige"}]},{"id":"p5","titre":"Phase 5 — Vérifications finales","col":"Vérification","num":true,"items":[{"n":"16","t":"Revérifier tout le système : eau fermée, aucune conduite pleine, valves dans la position d’hiver","crit":true},{"n":"—","t":"Photos prises : salle mécanique, valves, bassin vide, buses remisées"},{"n":"—","t":"Zone nettoyée, matériel rangé, aucun déchet chimique laissé sur place"}]},{"id":"mat","titre":"Matériel et pièces","col":"Matériel","col2":"Pièces de rechange","commun":true,"items":[{"t":"Compresseur, boyaux et raccords de soufflage"},{"t":"Pompe à puisard et boyau"},{"t":"Antigel biodégradable"},{"t":"Pinces et tournevis divers"},{"t":"Téflon"},{"t":"Bouchons de sorties de buses","g":2},{"t":"Joints de buses et de luminaires","g":2}]},{"id":"form","titre":"Formation des employés","col":"Sujet de formation","commun":true,"items":[{"t":"Séquence complète de l’hivernement de la fontaine (phases 1 à 5)"},{"t":"Démontage, nettoyage et remisage des buses et de la pompe"},{"t":"Soufflage sécuritaire à l’air comprimé (pression, protection des yeux et des oreilles)"},{"t":"Démonstration pratique réalisée sur le site, avec évaluation des participants"}]}]'::jsonb, '["Les buses, la pompe submersible et les luminaires se remisent selon les directives de leur fabricant : vérifier la fiche de la fontaine."]'::jsonb, 'L’HIVERNEMENT N’EST PAS UNE COURSE. UNE MAUVAISE EXÉCUTION PEUT AVOIR DES CONSÉQUENCES DE PLUSIEURS MILLIERS DE DOLLARS.', 3)
on conflict (code) do nothing;

notify pgrst, 'reload schema';
